1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { requests as allRequests, clients, assignees } from "@/lib/mock";
5	import { PageHeader } from "@/components/common/page-header";
6	import { ViewToggle, type ViewMode } from "@/components/inbox/view-toggle";
7	import { FilterBar, type InboxFilters } from "@/components/inbox/filter-bar";
8	import { InboxTable } from "@/components/inbox/inbox-table";
9	import { InboxKanban } from "@/components/inbox/inbox-kanban";
10	
11	const DEFAULT_FILTERS: InboxFilters = {
12	  search: "",
13	  status: "all",
14	  priority: "all",
15	  clientId: "all",
16	};
17	
18	export default function InboxPage() {
19	  const [view, setView] = useState<ViewMode>("table");
20	  const [filters, setFilters] = useState<InboxFilters>(DEFAULT_FILTERS);
21	
22	  const filtered = useMemo(() => {
23	    return allRequests.filter((r) => {
24	      if (filters.status !== "all" && r.status !== filters.status) return false;
25	      if (filters.priority !== "all" && r.priority !== filters.priority)
26	        return false;
27	      if (filters.clientId !== "all" && r.clientId !== filters.clientId)
28	        return false;
29	      if (filters.search) {
30	        const q = filters.search.toLowerCase();
31	        if (
32	          !r.title.toLowerCase().includes(q) &&
33	          !r.rawMessage.toLowerCase().includes(q)
34	        )
35	          return false;
36	      }
37	      return true;
38	    });
39	  }, [filters]);
40	
41	  const hasActiveFilters =
42	    filters.search !== "" ||
43	    filters.status !== "all" ||
44	    filters.priority !== "all" ||
45	    filters.clientId !== "all";
46	
47	  function handleClear() {
48	    setFilters(DEFAULT_FILTERS);
49	  }
50	
51	  return (
52	    <>
53	      <PageHeader
54	        title="Inbox"
55	        subtitle="All client requests in one place"
56	        actions={<ViewToggle value={view} onChange={setView} />}
57	      />
58	      <div className="space-y-4">
59	        <FilterBar
60	          filters={filters}
61	          onChange={setFilters}
62	          onClear={handleClear}
63	          hasActiveFilters={hasActiveFilters}
64	          clients={clients}
65	        />
66	        {view === "table" ? (
67	          <InboxTable
68	            requests={filtered}
69	            clients={clients}
70	            assignees={assignees}
71	            totalCount={allRequests.length}
72	            onClearFilters={handleClear}
73	          />
74	        ) : (
75	          <InboxKanban
76	            requests={filtered}
77	            clients={clients}
78	            assignees={assignees}
79	          />
80	        )}
81	      </div>
82	    </>
83	  );
84	}
