1	export type RequestStatus = "backlog" | "in_progress" | "review" | "delivered";
2	export type Priority = "low" | "normal" | "high" | "urgent";
3	export type Plan = "free" | "starter" | "growth" | "scale";
4	export type ActivityType =
5	  | "request_created"
6	  | "request_delivered"
7	  | "client_added"
8	  | "request_assigned"
9	  | "comment_added"
10	  | "brief_generated";
11	export type TrendDirection = "up" | "down" | "flat";
12	export type ServiceCategory =
13	  | "design"
14	  | "development"
15	  | "seo"
16	  | "content"
17	  | "video"
18	  | "ads";
19	export type AssigneeRole = "owner" | "designer" | "developer" | "pm";
20	export type IconName =
21	  | "users"
22	  | "inbox"
23	  | "activity"
24	  | "dollar-sign"
25	  | "clock";
26	
27	export interface Client {
28	  id: string;
29	  name: string;
30	  email: string;
31	  avatarUrl: string;
32	  company: string;
33	  plan: Plan;
34	  activeRequests: number;
35	  mrr: number;
36	  joinedAt: string;
37	}
38	
39	export interface Service {
40	  id: string;
41	  name: string;
42	  description: string;
43	  flatPrice: number;
44	  turnaroundDays: number;
45	  category: ServiceCategory;
46	  activeClients: number;
47	}
48	
49	export interface Assignee {
50	  id: string;
51	  name: string;
52	  avatarUrl: string;
53	  role: AssigneeRole;
54	}
55	
56	export interface Request {
57	  id: string;
58	  clientId: string;
59	  title: string;
60	  rawMessage: string;
61	  status: RequestStatus;
62	  priority: Priority;
63	  assigneeId: string;
64	  createdAt: string;
65	  slaDueAt: string;
66	  tags: readonly string[];
67	}
68	
69	export interface KpiMetric {
70	  id: string;
71	  label: string;
72	  value: string;
73	  rawValue: number;
74	  delta: number;
75	  trend: TrendDirection;
76	  iconName: IconName;
77	}
78	
79	export interface ActivityEvent {
80	  id: string;
81	  actorId: string;
82	  actorName: string;
83	  action: string;
84	  target: string;
85	  timestamp: string;
86	  type: ActivityType;
87	}
88	
89	export type SlaStatus = "ok" | "warning" | "breached";
90	
91	export function getSlaStatus(slaDueAt: string, now = "2026-04-10T12:00:00Z"): SlaStatus {
92	  const dueMs = new Date(slaDueAt).getTime();
93	  const nowMs = new Date(now).getTime();
94	  const diffHours = (dueMs - nowMs) / (1000 * 60 * 60);
95	  if (diffHours < 0) return "breached";
96	  if (diffHours < 24) return "warning";
97	  return "ok";
98	}
