28	function getInitials(name: string): string {
29	  return name
30	    .split(" ")
31	    .map((n) => n[0] ?? "")
32	    .slice(0, 2)
33	    .join("")
34	    .toUpperCase();
35	}
36	
37	
38	export function InboxTable({
39	  requests,
40	  clients,
41	  assignees,
42	  totalCount,
43	  onClearFilters,
44	}: InboxTableProps) {
45	  const clientMap = new Map(clients.map((c) => [c.id, c]));
46	  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));
47	
48	  return (
49	    <Card className="overflow-hidden border-border/70 shadow-card">
50	      <CardContent className="p-0">
51	        {requests.length === 0 ? (
52	          <EmptyState
53	            icon={Inbox}
54	            title="No matching requests"
55	            description="Try clearing your filters to see all requests."
56	            action={{ label: "Clear filters", onClick: onClearFilters }}
57	          />
58	        ) : (
59	          <>
60	            <Table className="[&_td]:px-3 [&_td]:py-3.5">
61	              <TableHeader className="bg-muted/40 [&_th]:h-11 [&_th]:px-3 [&_th]:text-xs [&_th]:font-semibold [&_th]:uppercase [&_th]:tracking-wide [&_th]:text-muted-foreground">
62	                <TableRow>
63	                  <TableHead className="pl-5 min-w-[200px]">Title</TableHead>
64	                  <TableHead className="min-w-[140px]">Client</TableHead>
65	                  <TableHead>Status</TableHead>
