1	const ANCHOR = new Date("2026-04-10T12:00:00Z");
2	
3	/** Signed hours from ANCHOR to the given ISO string. Negative = past. */
4	export function hoursFromNow(iso: string): number {
5	  const dueMs = new Date(iso).getTime();
6	  const nowMs = ANCHOR.getTime();
7	  return Math.round((dueMs - nowMs) / (1000 * 60 * 60));
8	}
9	
10	export function formatSlaChip(slaDueAt: string): {
11	  label: string;
12	  tone: "ok" | "warning" | "breached";
13	} {
14	  const hours = hoursFromNow(slaDueAt);
15	
16	  if (hours < 0) {
17	    const abs = Math.abs(hours);
18	    const label =
19	      abs >= 24 ? `${Math.floor(abs / 24)}d overdue` : `${abs}h overdue`;
20	    return { label, tone: "breached" };
21	  }
22	
23	  if (hours < 24) {
24	    return { label: `in ${hours}h`, tone: "warning" };
25	  }
26	
27	  const days = Math.floor(hours / 24);
28	  return { label: `in ${days}d`, tone: "ok" };
29	}
30	
31	export function formatRelative(iso: string): string {
32	  const diffMs = ANCHOR.getTime() - new Date(iso).getTime();
33	  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
34	
35	  if (diffHours < 1) return "just now";
36	  if (diffHours < 24) return `${diffHours}h ago`;
37	
38	  const diffDays = Math.floor(diffHours / 24);
39	  if (diffDays < 7) return `${diffDays}d ago`;
40	
41	  const diffWeeks = Math.floor(diffDays / 7);
42	  return `${diffWeeks}w ago`;
43	}
